INSERT INTO risk_criteria (company_id, code, name, version_number, method, probability_scale, severity_scale, probability_index_factors, level_bands, significant_from_level, is_default, status) VALUES (NULL, 'RM050-INDICES', 'Método de índices (R.M. 050-2013-TR)', 1, 'pxs_index', '[{"value": 4, "label": "Mínima (índice 4)"}, {"value": 12, "label": "Máxima (índice 12)"}]'::jsonb, '[{"value": 1, "label": "Lesión sin incapacidad / disconfort"}, {"value": 2, "label": "Lesión con incapacidad temporal / daño a la salud reversible"}, {"value": 3, "label": "Lesión con incapacidad permanente / daño a la salud irreversible"}]'::jsonb, '[{"code": "exposed_people", "label": "Personas expuestas", "levels": [{"value": 1, "label": "1 a 3"}, {"value": 2, "label": "4 a 12"}, {"value": 3, "label": "Más de 12"}]}, {"code": "procedures", "label": "Procedimientos existentes", "levels": [{"value": 1, "label": "Existen, son satisfactorios y suficientes"}, {"value": 2, "label": "Existen parcialmente y no son satisfactorios"}, {"value": 3, "label": "No existen"}]}, {"code": "training", "label": "Capacitación", "levels": [{"value": 1, "label": "Personal entrenado; conoce el peligro y lo previene"}, {"value": 2, "label": "Personal parcialmente entrenado"}, {"value": 3, "label": "Personal no entrenado"}]}, {"code": "exposure", "label": "Exposición al riesgo", "levels": [{"value": 1, "label": "Al menos una vez al año / esporádicamente"}, {"value": 2, "label": "Al menos una vez al mes / eventualmente"}, {"value": 3, "label": "Al menos una vez al día / permanentemente"}]}]'::jsonb, '[{"code": "trivial", "label": "Trivial", "min": 4, "max": 4, "color": "green"}, {"code": "tolerable", "label": "Tolerable", "min": 5, "max": 8, "color": "green"}, {"code": "moderate", "label": "Moderado", "min": 9, "max": 16, "color": "amber"}, {"code": "important", "label": "Importante", "min": 17, "max": 24, "color": "red"}, {"code": "intolerable", "label": "Intolerable", "min": 25, "max": 36, "color": "red"}]'::jsonb, 'moderate', true, 'active') ON CONFLICT DO NOTHING;
