INSERT INTO certificate_templates (company_id, code, name, description, orientation, paper_size, layout, body_template, code_prefix, shows_qr, shows_hours, shows_score, is_default, status) VALUES (NULL, 'CERT-DEFAULT', 'Certificado estándar EscudoSST', 'Plantilla horizontal A4 con logo de la empresa, firma del responsable, horas y código QR de verificación.', 'landscape', 'A4', '{"blocks": [{"id": "logo", "x": 40, "y": 30, "w": 160}, {"id": "title", "text": "CERTIFICADO", "y": 120, "align": "center", "size": 34}, {"id": "body", "y": 200, "align": "center", "size": 14}, {"id": "signature", "x": 120, "y": 430}, {"id": "qr", "x": 680, "y": 420, "w": 110}, {"id": "code", "x": 640, "y": 540, "size": 9}], "colors": {"primary": "#0D3B6E", "accent": "#1F7FD1"}}'::jsonb, 'Se certifica que {{holder_name}}, identificado(a) con documento {{holder_document_masked}}, aprobó el curso «{{course_title}}» con una duración de {{hours}} horas, emitido el {{issued_on}}. Vigente hasta: {{expires_on}}. Código: {{certificate_number}}. Verifique en {{verification_url}}.', 'CERT', true, true, false, true, 'active') ON CONFLICT DO NOTHING;
